int findFirstMissing(int array[], int start, int end) {
    // If start index is greater than end index, return the next element
    if (start > end) return end + 1;
    // If the start index does not match the value at that index, return start
    if (start != array[start]) return start;

    int mid = (start + end) / 2; // Calculate mid index
    // If the value at mid index matches mid, search in the right half
    if (array[mid] == mid) return findFirstMissing(array, mid + 1, end);

    // Otherwise, search in the left half
    return findFirstMissing(array, start, mid);
}

