public class Program
{
    public static int FindSize(int N)
    {
        if (N == 0) return 1;
        if (N == 1) return 1;
        int size = 2 * FindSize(N / 2) + 1;
        return size;
    }

    public static int CountOnes(int N, int L, int R)
    {
        if (L > R)
        {
            return 0;
        }
        if (N <= 1)
        {
            return N;
        }
        int ret = 0;
        int M = N / 2;
        int Siz_M = FindSize(M);
        if (L <= Siz_M)
        {
            ret += CountOnes(N / 2, L, Math.Min(Siz_M, R));
        }
        if (L <= Siz_M + 1 && Siz_M + 1 <= R)
        {
            ret += N % 2;
        }
        if (Siz_M + 1 < R)
        {
            ret += CountOnes(N / 2, Math.Max(1, L - Siz_M - 1), R - Siz_M - 1);
        }
        return ret;
    }

    public static void Main()
    {
        int N = 7, L = 2, R = 5;
        Console.WriteLine(CountOnes(N, L, R));
    }
}

