    {
        if (n == 0) FindLCM(arr);
        for (int j = i; j <= n; j++)
        {
            arr.Add(j);
            FindWays(arr, j, n - j);
            arr.RemoveAt(arr.Count - 1);
        }
    }

    static void LandauFunction(int n)
    {
        List<int> arr = new List<int>();
        FindWays(arr, 1, n);
        Console.WriteLine(Landau);
