    static int minSum(const std::vector<int>& A, int N) {
        std::unordered_map<int, int> mp;
        int sum = 0;

        for (int i = 0; i < N; i++) {
            sum += A[i];
            if (mp.find(A[i]) != mp.end()) {
                mp[A[i]]++;
            } else {
                mp[A[i]] = 1;
            }
        }

        int minSum = std::numeric_limits<int>::max();
        for (const auto& it : mp) {
            minSum = std::min(minSum, sum - (it.first * it.second));
        }

        return minSum;
    }
