    static int findSize(int N) {
        if (N == 0) return 1;
        if (N == 1) return 1;
        int Size = 2 * findSize(N / 2) + 1;
        return Size;
    }

    static int CountOnes(int N, int L, int R) {
        if (L > R) {
            return 0;
        }
        if (N <= 1) {
            return N;
        }
        int ret = 0;
        int M = N / 2;
        int Siz_M = findSize(M);
        if (L <= Siz_M) {
            ret += CountOnes(N / 2, L, std::min(Siz_M, R));
        }
        if (L <= Siz_M + 1 && Siz_M + 1 <= R) {
            ret += N % 2;
        }
        if (Siz_M + 1 < R) {
            ret += CountOnes(N / 2, std::max(1, L - Siz_M - 1), R - Siz_M - 1);
        }
        return ret;
    }
};

int main() {
    int N = 7, L = 2, R = 5;
    std::cout << GFG::CountOnes(N, L, R) << std::endl;
    return 0;
}

