class GFG {
public:
    static long func(const std::vector<int>& arr, int n) {
        double ans = 0;
        int maxx = 0;
        std::vector<double> freq(100005, 0.0);
        int temp;

        for (int i = 0; i < n; i++) {
            temp = arr[i];
            freq[temp]++;
            maxx = std::max(maxx, temp);
        }

        for (int i = 1; i <= maxx; i++) {
            freq[i] += freq[i - 1];
        }

        for (int i = 1; i <= maxx; i++) {
            if (freq[i] != 0) {
                double j;
                double cur = std::ceil(0.5 * i) - 1.0;
                for (j = 1.5;; j++) {
                    int val = std::min(maxx, static_cast<int>(std::ceil(i * j) - 1.0));
                    int times = static_cast<int>(freq[i] - freq[i - 1]);
                    int con = static_cast<int>(j - 0.5);
                    ans += times * con * (freq[static_cast<int>(val)] - freq[static_cast<int>(cur)]);
                    cur = val;
                    if (val == maxx) break;
                }
            }
        }
        return static_cast<long>(ans);
    }
};

