        return 1
    if N == 1:
        return 1
    size = 2 * find_size(N // 2) + 1
    return size

def count_ones(N, L, R):
    if L > R:
        return 0
    if N <= 1:
        return N
    ret = 0
    M = N // 2
    siz_m = find_size(M)
    if L <= siz_m:
        ret += count_ones(N // 2, L, min(siz_m, R))
    if L <= siz_m + 1 and siz_m + 1 <= R:
        ret += N % 2
    if siz_m + 1 < R:
        ret += count_ones(N // 2, max(1, L - siz_m - 1), R - siz_m - 1)
    return ret

