class GFG {
    public static int $MAXN = 1000001;
    public static array $spf = [];
    public static array $hash1 = [];

    public static function sieve() {
        self::$spf[1] = 1;
        for ($i = 2; $i < self::$MAXN; $i++) {
            self::$spf[$i] = $i;
        }
        for ($i = 4; $i < self::$MAXN; $i += 2) {
            self::$spf[$i] = 2;
        }
        for ($i = 3; $i * $i < self::$MAXN; $i++) {
            if (self::$spf[$i] == $i) {
                for ($j = $i * $i; $j < self::$MAXN; $j += $i) {
                    if (self::$spf[$j] == $j) {
                        self::$spf[$j] = $i;
                    }
                }
            }
        }
    }

    public static function getFactorization($x) {
        while ($x != 1) {
            $temp = self::$spf[$x];
            if ($x % $temp == 0) {
                self::$hash1[$temp]++;
                $x = $x / $temp;
            }
            while ($x % $temp == 0) {
                $x = $x / $temp;
            }
        }
    }

    public static function check($x) {
        while ($x != 1) {
            $temp = self::$spf[$x];
            if ($x % $temp == 0 && self::$hash1[$temp] > 1) {
                return false;
            }
            while ($x % $temp == 0) {
                $x = $x / $temp;
            }
        }
        return true;
    }

    public static function hasValidNum($arr, $n) {
        self::sieve();
        for ($i = 0; $i < $n; $i++) {
            self::getFactorization($arr[$i]);
        }
        for ($i = 0; $i < $n; $i++) {
            if (self::check($arr[$i])) {
                return true;
            }
        }
        return false;
    }

    public static function main() {
        $arr = [2, 8, 4, 10, 6, 7];
        $n = count($arr);
        if (self::hasValidNum($arr, $n)) {
            echo "Yes\n";
        } else {
            echo "No\n";
        }
    }
}

