        for ($col = $n - 1; $col >= 0; $col--) {
            for ($row = 0; $row < $m; $row++) {
                $right = ($col == $n - 1) ? 0 : $goldTable[$row][$col + 1];
                $right_up = ($row == 0 || $col == $n - 1) ? 0 : $goldTable[$row - 1][$col + 1];
                $right_down = ($row == $m - 1 || $col == $n - 1) ? 0 : $goldTable[$row + 1][$col + 1];
                $goldTable[$row][$col] = $gold[$row][$col] + max($right, max($right_up, $right_down));
