        double SP = 2400;
        double P = 30;
        loss(SP, P);
    }
}

import java.util.Arrays;

public class PrimeFactorization {
    static final int MAXN = 10001;
    static int[] spf = new int[MAXN];
    static int[] hash1 = new int[MAXN];

    static void sieve() {
        spf[1] = 1;
        for (int i = 2; i < MAXN; i++) {
            spf[i] = i;
        }
        for (int i = 4; i < MAXN; i += 2) {
            spf[i] = 2;
        }
        for (int i = 3; i * i < MAXN; i++) {
            if (spf[i] == i) {
                for (int j = i * i; j < MAXN; j += i) {
                    if (spf[j] == j) {
                        spf[j] = i;
                    }
                }
            }
        }
    }

    static void getFactorization(int x) {
        while (x != 1) {
            int temp = spf[x];
            if (x % temp == 0) {
                hash1[temp]++;
                x /= temp;
            }
            while (x % temp == 0) {
                x /= temp;
            }
        }
    }

    static boolean check(int x) {
        while (x != 1) {
            int temp = spf[x];
            if (x % temp == 0 && hash1[temp] > 1) {
                return false;
            }
            while (x % temp == 0) {
                x /= temp;
            }
        }
        return true;
    }

    static boolean hasValidNum(int[] arr, int n) {
        sieve();
        Arrays.fill(hash1, 0);
        for (int i = 0; i < n; i++) {
            getFactorization(arr[i]);
        }
        for (int i = 0; i < n; i++) {
            if (check(arr[i])) {
                return true;
            }
        }
        return false;
    }

    public static void main(String[] args) {
        int[] arr = {2, 8, 4, 10, 6, 7};
        int n = arr.length;
        if (hasValidNum(arr, n)) {
            System.out.println("Yes");
        } else {
            System.out.println("No");
        }
    }
}

