import java.util.Arrays;

public class PartitionCalculator {
    public static int partitions(int n) {
        int[] p = new int[n + 1];
        Arrays.fill(p, 0);
        p[0] = 1;

        for (int i = 1; i <= n; i++) {
            int k = 1;
            while ((k * (3 * k - 1)) / 2 <= i) {
                p[i] += ((k % 2 != 0 ? 1 : -1) * p[i - (k * (3 * k - 1)) / 2]);
                if (k > 0) k *= -1; else k = 1 - k;
            }
        }
        return p[n];
    }

    public static void main(String[] args) {
        int N = 20;
        System.out.println(partitions(N));
    }
}

