class GFG:
    def find_size(N):
        if N == 0:
            return 1
        if N == 1:
            return 1
        size = 2 * GFG.find_size(N // 2) + 1
        return size

    def count_ones(N, L, R):
        if L > R:
            return 0
        if N <= 1:
            return N
        ret = 0
        M = N // 2
        siz_M = GFG.find_size(M)
        if L <= siz_M:
            ret += GFG.count_ones(N // 2, L, min(siz_M, R))
        if L <= siz_M + 1 and siz_M + 1 <= R:
            ret += N % 2
        if siz_M + 1 < R:
            ret += GFG.count_ones(N // 2, max(1, L - siz_M - 1), R - siz_M - 1)
        return ret

