public class Main {
    public static int func(int[] arr, int n) {
        int ans = 0;
        int maxx = 0;
        int[] freq = new int[100005];
        int temp = 0;

        for (int i = 0; i < n; i++) {
            temp = arr[i];
            freq[temp]++;
            maxx = Math.max(maxx, temp);
        }

        for (int i = 1; i <= maxx; i++) {
            freq[i] += freq[i - 1];
        }

        for (int i = 1; i <= maxx; i++) {
            if (freq[i] != 0) {
                int value = 0;
                double cur = Math.ceil(0.5 * i) - 1.0;
                double j = 1.5;

                while (true) {
                    int val = Math.min(maxx, (int)(Math.ceil(i * j) - 1.0));
                    int times = (freq[i] - freq[i - 1]);
                    double con = j - 0.5;
                    ans += times * con * (freq[val] - freq[(int)cur]);
                    cur = val;
                    if (val == maxx) {
                        break;
                    }
                    j += 1;
                }
            }
        }
        return (int) ans;
    }

    public static void main(String[] args) {
        int[] arr = {1, 2, 3};
        int n = arr.length;
        System.out.println(func(arr, n));
    }
}

