function gcd(a, b) {
    if (a === 0) return b;
    return gcd(b % a, a);
}

function lcm(a, b) {
    return (a * b) / gcd(a, b);
}

function findLCM(arr) {
    let nth_lcm = arr[0];
    for (let i = 1; i < arr.length; i++) {
        nth_lcm = lcm(nth_lcm, arr[i]);
    }
    Landau = Math.max(Landau, nth_lcm);
}

function findWays(arr, i, n) {
    if (n === 0) findLCM(arr);
    for (let j = i; j <= n; j++) {
        arr.push(j);
        findWays(arr, j, n - j);
        arr.pop();
    }
}

