function isPrime(n) {
    if (n < 1) return false; // Handle cases where n is less than 1
    if (n === 1) return true;
    if (n <= 3) return true;
    if (n % 2 === 0 || n % 3 === 0) return false;
    for (let i = 5; i * i <= n; i += 6) {
        if (n % i === 0 || n % (i + 2) === 0) return false;
    }
    return true;
}

