function func(arr, n) {
    let ans = 0;
    let maxx = 0;
    let freq = new Array(100005).fill(0);
    let temp;

    for (let i = 0; i < n; i++) {
        temp = arr[i];
        freq[temp]++;
        maxx = Math.max(maxx, temp);
    }

    for (let i = 1; i <= maxx; i++) {
        freq[i] += freq[i - 1];
    }

    for (let i = 1; i <= maxx; i++) {
        if (freq[i] !== 0) {
            let j;
            let cur = Math.ceil(0.5 * i) - 1.0;
            for (j = 1.5;; j++) {
                let val = Math.min(maxx, Math.ceil(i * j) - 1.0);
                let times = freq[i] - freq[i - 1];
                let con = j - 0.5;
                ans += times * con * (freq[val] - freq[cur]);
                cur = val;
                if (val === maxx) break;
            }
        }
    }
    return ans;
}

