import java.util.HashMap;
import java.util.Map;

public class Main {
    public static int minSum(int[] A, int N) {
        Map<Integer, Integer> mp = new HashMap<>();
        int sum = 0;
        for (int i = 0; i < N; i++) {
            sum += A[i];
            mp.put(A[i], mp.getOrDefault(A[i], 0) + 1);
        }
        int minSum = Integer.MAX_VALUE;
        for (Map.Entry<Integer, Integer> it : mp.entrySet()) {
            minSum = Math.min(minSum, sum - (it.getKey() * it.getValue()));
        }
        return minSum;
    }

    public static void main(String[] args) {
        int[] arr = {4, 5, 6, 6};
        int N = arr.length;
        System.out.print(minSum(arr, N) + " ");
    }
}

import java.util.ArrayList;
import java.util.List;

public class Main {
    public static void maxAdjacent(int[] arr, int N) {
        List<Integer> res = new ArrayList<>();
        for (int i = 1; i < N - 1; i++) {
            int prev = arr[0];
            int maxi = Integer.MIN_VALUE;
            for (int j = 1; j < N; j++) {
                if (i == j) continue;
                maxi = Math.max(maxi, Math.abs(arr[j] - prev));
                prev = arr[j];
            }
            res.add(maxi);
        }
        for (int j = 0; j < res.size(); j++) {
            System.out.print(res.get(j) + " ");
        }
        System.out.print(" ");
    }

    public static void main(String[] args) {
        int[] arr = {1, 3, 4, 7, 8};
        int N = arr.length;
        maxAdjacent(arr, N);
    }
}

public class CountOnesCalculator {

    // Function to find the size based on the given N
    public static int findSize(int N) {
        if (N == 0) return 1;
        if (N == 1) return 1;
        int Size = 2 * findSize((int) Math.floor(N / 2)) + 1;
        return Size;
    }

    // Function to count ones between L and R for the given N
    public static int CountOnes(int N, int L, int R) {
        if (L > R) {
            return 0;
        }
        if (N <= 1) {
            return N;
        }
        int ret = 0;
        int M = (int) Math.floor(N / 2);
        int Siz_M = findSize(M);

        if (L <= Siz_M) {
            ret += CountOnes((int) Math.floor(N / 2), L, Math.min(Siz_M, R));
        }
        if (L <= Siz_M + 1 && Siz_M + 1 <= R) {
            ret += N % 2;
        }
        if (Siz_M + 1 < R) {
            ret += CountOnes((int) Math.floor(N / 2), Math.max(1, L - Siz_M - 1), R - Siz_M - 1);
        }
        return ret;
    }

    public static void main(String[] args) {
        int N = 7, L = 2, R = 5;
        System.out.println(CountOnes(N, L, R));
    }
}

