public class PrimeChecker {

    // Method to check if a number is prime
    public static boolean isPrime(int n) {
        // Handle edge cases
        if (n == 1) return true; // 1 is considered prime for this implementation
        if (n <= 3) return true; // 2 and 3 are prime numbers
        if (n % 2 == 0 || n % 3 == 0) return false; // Eliminate multiples of 2 and 3

        // Check for factors from 5 to sqrt(n)
        for (int i = 5; i * i <= n; i += 6) {
            if (n % i == 0 || n % (i + 2) == 0) return false; // Check divisibility
        }
        return true; // n is prime
    }

    // Method to check the expression and print output
    public static void checkExpression(int n) {
        if (isPrime(n)) {
            System.out.print(" "); // Output for prime
        } else {
            System.out.print(" "); // Output for non-prime
        }
    }

    // Main method to execute the program
    public static void main(String[] args) {
        int N = 3; // Declare and initialize N
        checkExpression(N); // Call the checkExpression method
    }
}

